//! Host lifecycle/connection scheduling on fictional PostgreSQL; all provider traffic is loopback.
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn configured_execution_worker_prepares_saved_queue_independently_of_coordinator_mode_without_dispatch(){
    let(mut observer,inspection)=listing_fixture().await;let eligible=listing_observe(&mut observer,&inspection,listing_report(&inspection)).await.unwrap();sqlx::query("UPDATE rust_agent_control SET mode='STOPPED'").execute(&mut observer).await.unwrap();let config=Arc::new(Configuration::from_values(&browser_values()).unwrap());let execution=config.connect(true).await.unwrap();let stop=CancellationToken::new();let shutdown=stop.clone();let worker=tokio::spawn(async move{automated_apply_agents::recovery::supervise(&config,execution,Wake::default(),shutdown).await});let key=format!("apply_work:{}",eligible["id"].as_str().unwrap());let mut prepared=Value::Null;
    for _ in 0..200{prepared=browser_pref(&mut observer,&key).await;if prepared["packet_id"].is_string(){break;}tokio::time::sleep(Duration::from_millis(10)).await;}
    assert!(prepared["packet_id"].is_string(),"configured worker must perform local factual preparation");assert_eq!(prepared["stage"],"NEEDS_INPUT");assert_eq!(prepared["admitted_actions"],json!([]));for _ in 0..100{let exists:bool=sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM owner_preferences WHERE key='apply_schedule:naukri')").fetch_one(&mut observer).await.unwrap();if exists{break;}tokio::time::sleep(Duration::from_millis(10)).await;}let status=browser_pref(&mut observer,"apply_schedule:naukri").await;assert_eq!(status["data"]["provider_calls"],0);assert_eq!(status["data"]["application_dispatch"],false);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut observer).await.unwrap(),0);stop.cancel();assert!(tokio::time::timeout(Duration::from_secs(3),worker).await.unwrap().unwrap().is_ok());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn full_host_quiesce_pauses_running_queue_once_and_retains_spent_apply_and_saved_limits(){
    let(mut observer,work,_)=submission_fixture().await;let before=browser_pref(&mut observer,"application_queue_policy").await;let config=Arc::new(Configuration::from_values(&host_values()).unwrap());let control=config.connect(false).await.unwrap();let api=Api::new(config,control,Wake::default());server::quiesce(&api).await.unwrap();let after=browser_pref(&mut observer,"application_queue_policy").await;assert_eq!(after["state"],"PAUSED");assert_eq!(after["revision"],163);assert_eq!(after["policy"],before["policy"]);let current=browser_pref(&mut observer,&format!("apply_work:{}",work["id"].as_str().unwrap())).await;assert_eq!(current["admitted_actions"],work["admitted_actions"]);assert_eq!(lifecycle::control(&mut observer).await.unwrap().mode,Mode::Paused);server::quiesce(&api).await.unwrap();assert_eq!(browser_pref(&mut observer,"application_queue_policy").await,after);
}
fn queue_runtime_values()->BTreeMap<String,String>{let mut values=browser_values();let corpus:Value=serde_json::from_str(include_str!("../../../document-worker/tests/fixtures/pdf-corpus.json")).unwrap();values.insert("RESUME_ENCRYPTION_KEY".into(),corpus["fernet"]["key"].as_str().unwrap().into());values}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn queue_generation_driver_resolves_facts_and_releases_its_only_transient_connection(){
    let(mut observer,work,resumes)=questionnaire_fixture().await;queued_questionnaire(&mut observer,&work,"What is your full name?",&resumes).await;let config=Arc::new(Configuration::from_values(&queue_runtime_values()).unwrap());let control=config.connect(false).await.unwrap();let api=Api::new(config,control,Wake::default());let stop=CancellationToken::new();let driver=tokio::spawn(server::serve_queue_generation(api.clone(),stop.clone()));let key=format!("apply_work:{}",work["id"].as_str().unwrap());let mut current=Value::Null;
    for _ in 0..400{current=browser_pref(&mut observer,&key).await;if current["operation"]=="refresh_questionnaire_profile"{break;}tokio::time::sleep(Duration::from_millis(20)).await;}
    assert_eq!(current["operation"],"refresh_questionnaire_profile");assert_eq!(current["questionnaire_answer"]["resolved_source"],"candidate_profile");assert_eq!(current["admitted_actions"],work["admitted_actions"]);let mut active=99;
    for _ in 0..100{active=sqlx::query_scalar::<_,i64>("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND application_name='automated-apply:api'").fetch_one(&mut observer).await.unwrap();if active==1{break;}tokio::time::sleep(Duration::from_millis(10)).await;}assert_eq!(active,1);stop.cancel();assert!(tokio::time::timeout(Duration::from_secs(3),driver).await.unwrap().unwrap().is_ok());
}
#[derive(Clone)]
struct QueueModelGate{calls:Arc<AtomicUsize>,entered:Arc<tokio::sync::Notify>,release:Arc<tokio::sync::Notify>,owner:Uuid}
async fn queue_model_response(axum::extract::State(state):axum::extract::State<QueueModelGate>,axum::Json(_body):axum::Json<Value>)->axum::Json<Value>{state.calls.fetch_add(1,Ordering::SeqCst);state.entered.notify_one();state.release.notified().await;let reference=json!({"source_type":"verified_project","source_id":format!("{}:project:0",state.owner)});let content=json!({"answer":"I built Rust workers.","evidence_references":[reference],"claims":[{"text":"I built Rust workers.","quote":"I built Rust workers.","source":reference}],"opportunity_claims":[]});axum::Json(json!({"finish_reason":"COMPLETE","message":{"role":"assistant","content":[{"type":"text","text":content.to_string()}]},"usage":{"tokens":{"input_tokens":100,"output_tokens":10}}}))}
async fn queue_model_fixture(owner:Uuid)->(QueueModelGate,String,CancellationToken,tokio::task::JoinHandle<()>) {let state=QueueModelGate{calls:Arc::new(AtomicUsize::new(0)),entered:Arc::new(tokio::sync::Notify::new()),release:Arc::new(tokio::sync::Notify::new()),owner};let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let addr=listener.local_addr().unwrap();let stop=CancellationToken::new();let shutdown=stop.clone();let router=axum::Router::new().route("/v2/chat",axum::routing::post(queue_model_response)).with_state(state.clone());let server=tokio::spawn(async move{axum::serve(listener,router).with_graceful_shutdown(shutdown.cancelled_owned()).await.unwrap();});(state,format!("http://{addr}/v2/chat"),stop,server)}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn queue_background_inference_shares_http_slot_keeps_owner_control_responsive_and_stop_rejects_late_answer(){
    let(mut observer,work,resumes)=questionnaire_fixture().await;queued_questionnaire(&mut observer,&work,"Describe a project you built",&resumes).await;let owner=work["candidate_profile_id"].as_str().unwrap().parse().unwrap();let(model,endpoint,model_stop,model_server)=queue_model_fixture(owner).await;let mut values=queue_runtime_values();values.extend(answer_cloud_values(endpoint));values.insert("LLM_PROVIDER".into(),"gemini".into());let config=Arc::new(Configuration::from_values(&values).unwrap());let control=config.connect(false).await.unwrap();let api=Api::new(config,control,Wake::default());let stop=CancellationToken::new();let driver=tokio::spawn(server::serve_queue_generation(api.clone(),stop.clone()));let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let shutdown=stop.clone();let http_api=api.clone();let http_server=tokio::spawn(async move{axum::serve(listener,server::router(http_api).into_make_service_with_connect_info::<std::net::SocketAddr>()).with_graceful_shutdown(shutdown.cancelled_owned()).await.unwrap();});tokio::time::timeout(Duration::from_secs(8),model.entered.notified()).await.unwrap();
    let mut lock=observer.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE NOWAIT").execute(&mut *lock).await.unwrap();lock.commit().await.unwrap();let http=client();let profile=tokio::time::timeout(Duration::from_secs(1),http.get(format!("http://{address}/api/v1/profile")).bearer_auth(HOST_TOKEN).send()).await.unwrap().unwrap();assert_eq!(profile.status(),200);let denied=http.post(format!("http://{address}/api/v1/application-answers/generate")).bearer_auth(HOST_TOKEN).json(&json!({"question":"What is your full name?"})).send().await.unwrap();assert_eq!(denied.status(),429);
    let stopped=tokio::time::timeout(Duration::from_secs(1),http.post(format!("http://{address}/api/v1/execution/queue/control")).bearer_auth(HOST_TOKEN).json(&json!({"action":"stop","expected_revision":162})).send()).await.unwrap().unwrap();assert_eq!(stopped.status(),200);model.release.notify_one();let key=format!("apply_work:{}",work["id"].as_str().unwrap());
    for _ in 0..200{let recorded:bool=sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM owner_preferences WHERE key='apply_generation:naukri')").fetch_one(&mut observer).await.unwrap();if recorded{break;}tokio::time::sleep(Duration::from_millis(10)).await;}
    let current=browser_pref(&mut observer,&key).await;assert_eq!(current["stage"],"PAUSED");assert!(current["questionnaire_answer"].is_null());assert_eq!(current["admitted_actions"],work["admitted_actions"]);assert_eq!(model.calls.load(Ordering::SeqCst),1);assert_eq!(sqlx::query_scalar::<_,i32>("SELECT requests FROM llm_monthly_usage WHERE provider='cohere'").fetch_one(&mut observer).await.unwrap(),1);assert_eq!(browser_pref(&mut observer,"application_queue_policy").await["state"],"STOPPED");assert!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND application_name='automated-apply:api'").fetch_one(&mut observer).await.unwrap()<=2);stop.cancel();assert!(tokio::time::timeout(Duration::from_secs(3),driver).await.unwrap().unwrap().is_ok());http_server.await.unwrap();model_stop.cancel();model_server.await.unwrap();
}
